parameters.jsCode:
// Normaliza o lead vindo do formulário /diagnostico
// - valida o mínimo (consentimento, e-mail, empresa)
// - devolve SÓ as colunas da planilha, na mesma grafia dos cabeçalhos
// - protege contra fórmulas: no Sheets, texto começando com = + - @ vira fórmula/número
//   (ex.: +5527999998888 viraria número). O apóstrofo força texto e não aparece na célula.

const COLUNAS = [
  'lead_id','enviado_em','status','empresa','segmento','cidade','rede_social','rede_social_link',
  'site','concorrente','objetivo','interesse','ja_investiu','investimento','visao_3_anos',
  'nome','email','telefone','telefone_e164','consentimento',
  'utm_source','utm_medium','utm_campaign','utm_content','utm_term','utm_id',
  'fbclid','gclid','gbraid','wbraid','ttclid','li_fat_id',
  'primeiro_toque','referrer','landing_page','user_agent'
];

const b = $input.first().json.body || {};

if (b.consentimento !== 'sim') throw new Error('Lead recusado: sem consentimento');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(b.email || '').trim())) throw new Error('Lead recusado: e-mail inválido');
if (String(b.empresa || '').trim().length < 2) throw new Error('Lead recusado: empresa vazia');

const limpar = v => {
  let s = String(v ?? '').trim().slice(0, 1000);
  if (/^[=+\-@]/.test(s)) s = "'" + s;
  return s;
};

const lead = {};
for (const c of COLUNAS) lead[c] = limpar(b[c]);
lead.status = 'novo';
if (!lead.lead_id) lead.lead_id = $execution.id;
if (!lead.enviado_em) lead.enviado_em = new Date().toISOString();

return [{ json: lead }];

